prompt --application/shared_components/user_interface/templates/list/marquee_links
begin
wwv_flow_imp_shared.create_list_template(
 p_id=>wwv_flow_imp.id(998290033883084337)
,p_list_template_before_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<div class="amc-TMarqueeLinks #COMPONENT_CSS_CLASSES#" id="#LIST_ID#">',
'<span class="amc-TMarqueeLinks-pulse" aria-hidden="true"></span>',
'<div class="amc-TMarqueeLinks-viewport">',
'<ul class="amc-TMarqueeLinks-group">'))
,p_list_template_after_rows=>wwv_flow_string.join(wwv_flow_t_varchar2(
'</ul>',
'</div>',
'<button type="button" class="amc-TMarqueeLinks-toggle" aria-pressed="false" hidden><span class="amc-TMarqueeLinks-toggleIcon" aria-hidden="true"></span><span class="amc-TMarqueeLinks-toggleLabel">Pause scrolling</span></button>',
'</div>'))
,p_list_template_current=>'<li class="amc-TMarqueeLinks-item is-current"><a class="amc-TMarqueeLinks-link" href="#LINK#" aria-current="page"><span class="amc-TMarqueeLinks-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMarqueeLinks-tag">#A01#</span><span class="amc-TMarqueeLinks-label">#TEXT#</span></a></li>'
,p_list_template_noncurrent=>'<li class="amc-TMarqueeLinks-item"><a class="amc-TMarqueeLinks-link" href="#LINK#"><span class="amc-TMarqueeLinks-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span><span class="amc-TMarqueeLinks-tag">#A01#</span><span class="amc-TMarqueeLinks-label">#TEXT#</span></a></li>'
,p_list_template_name=>'AMC Marquee Links'
,p_internal_name=>'AMC_TPL_MARQUEE_LINKS'
,p_javascript_file_urls=>'#APP_FILES#amc-templates/amc-tpl-marquee-links.js'
,p_theme_id=>42
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-marquee-links.css'
,p_a01_label=>'Tag'
,p_list_template_comment=>'List template for an announcement or quick-link ticker. The entries scroll sideways in a seamless loop (the JavaScript file repeats the entries with copies that are hidden from screen readers and skipped by the Tab key), reverse direction in right-to-left languages, and pause while the pointer is over the strip, while a link has keyboard focus, or after the pause button is pressed. Use the Tag attribute (A01) for a short label such as New, Due today or Partner shown as a chip before the text. Template options: Slow and Fast change the speed, Reverse scrolls the other way, Band paints a solid primary-color strip, and Plain removes the frame for use inside a page header. Without JavaScript, and under reduced motion, the entries sit still as a wrapped row of links. The pause button label is English text in the After List Entries template; translate it there if needed.'
);
end;
